import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s = br.readLine();if (s == null || s.length() < 4) {System.out.println("NO");return;}if (check(s, "AB", "BA") || check(s, "BA", "AB")) {System.out.println("YES");} else {System.out.println("NO");}}private static boolean check(String s, String first, String second) {int firstIdx = s.indexOf(first);if (firstIdx == -1) return false;int secondIdx = s.indexOf(second, firstIdx + 2);return secondIdx != -1;}}